// Some portions generated by Claude
import test from 'node:test';
import assert from 'node:assert/strict';
import {computeGraphLayout} from '../../../main/frontend/graph-explorer/graph-layout-engine.ts';
import {hubNeighborhood} from './fixtures/layout-hub-neighborhood.mjs';
import {routeReadability} from './fixtures/readability-measurements.mjs';
import {indexedIntersections} from './fixtures/layout-measurements.mjs';
import {computeHubNeighborhoodLayout} from '../../../main/frontend/graph-explorer/graph-layout-hub.ts';
import {layoutMetrics} from './support/benchmark-layout.mjs';

test('a large terminal fan balances routed clarity with a bounded footprint', async () => {
  const graph = hubNeighborhood(), before = structuredClone(graph);
  const result = await computeGraphLayout(graph);
  assert.equal(indexedIntersections(graph,result.positions),0);
  const metrics = routeReadability(graph,result.positions,result.bends,result.routes);
  assert.ok(graph.edges.filter(e=>e.source.startsWith('leaf')).reduce((sum,e)=>sum+(metrics.obstructionsByEdge[e.id]??0),0)<=5);
  assert.ok(metrics.exactRoutedObstructions <= 5);
  // Baseline 5007f56: 57 obstructions, 3.05M area. An empty outer arc has
  // fewer collisions but >20M area, making the connected core unreadable.
  // The organic engine draws the 75 leaves as a C-shaped fan open towards the
  // core: no obstruction and one crossing, for 12.3M px² and long arrows to the
  // far ends of its columns (95th percentile 2.5k px).
  const geometry=layoutMetrics(graph,result.positions);
  assert.ok(geometry.area < 13_000_000, `area ${geometry.area}`);
  assert.ok(geometry.p95Edge < 2600, `95th-percentile edge ${geometry.p95Edge}`);
  assert.deepEqual(graph,before);
});

test('hub specialization does not override constrained or incremental layouts', () => {
  const graph = hubNeighborhood();
  const forbidden = () => {throw new Error('must not solve core');};
  for (const options of [{incremental:true},{refine:true},{repairOnly:true},{localNodeIds:new Set(['award'])},
    {groups:[{id:'group',name:'Keep together',nodeIds:['award','c0']}]}, {nodeSizes:new Map()}]) {
    assert.equal(computeHubNeighborhoodLayout(graph,options,forbidden),undefined);
  }
  graph.nodes[0].pinned=true;
  assert.equal(computeHubNeighborhoodLayout(graph,{},forbidden),undefined);
  graph.nodes[0].pinned=false;
  graph.edges.push({...graph.edges.at(-1),id:'parallel'});
  assert.equal(computeHubNeighborhoodLayout(graph,{},forbidden),undefined);
});

test('hub arc accounts for long labels and is deterministic', async () => {
  const graph = hubNeighborhood(40);
  graph.nodes.filter(n=>n.id.startsWith('leaf')).forEach((n,i)=>{n.label=`Research institute with a long name ${i}`;});
  const first=await computeGraphLayout(graph), second=await computeGraphLayout(graph);
  assert.deepEqual(first.positions,second.positions);
  assert.equal(indexedIntersections(graph,first.positions),0);
  assert.equal(first.positions.size,graph.nodes.length);
  const metrics=routeReadability(graph,first.positions,first.bends,first.routes);
  assert.ok(graph.edges.filter(e=>e.source.startsWith('leaf')).reduce((sum,e)=>sum+(metrics.obstructionsByEdge[e.id]??0),0)<=6);
});
